select coalesce(jsonb_agg(item order by item->>'kind',item->>'key'),'[]'::jsonb) as catalog from (
 select jsonb_build_object('kind','relation','key',n.nspname||'.'||c.relname,'value',jsonb_build_object('kind',c.relkind,'owner',pg_catalog.pg_get_userbyid(c.relowner),'persistence',c.relpersistence,'rls',c.relrowsecurity,'forced',c.relforcerowsecurity)) item
 from pg_catalog.pg_class c join pg_catalog.pg_namespace n on n.oid=c.relnamespace where n.nspname in ('public','touchline_private') and c.relkind in ('r','v','m','S','f','p')
 and not exists(select 1 from pg_catalog.pg_depend d where d.objid=c.oid and d.classid='pg_catalog.pg_class'::regclass and d.deptype='e')
 union all
 select jsonb_build_object('kind','column','key',n.nspname||'.'||c.relname||'.'||a.attname,'value',jsonb_build_object('position',a.attnum,'type',pg_catalog.format_type(a.atttypid,a.atttypmod),'notNull',a.attnotnull,'default',pg_catalog.pg_get_expr(ad.adbin,ad.adrelid),'identity',a.attidentity,'generated',a.attgenerated))
 from pg_catalog.pg_attribute a join pg_catalog.pg_class c on c.oid=a.attrelid join pg_catalog.pg_namespace n on n.oid=c.relnamespace left join pg_catalog.pg_attrdef ad on ad.adrelid=a.attrelid and ad.adnum=a.attnum
 where n.nspname in ('public','touchline_private') and c.relkind in ('r','v','m','f','p') and a.attnum>0 and not a.attisdropped
 and not exists(select 1 from pg_catalog.pg_depend d where d.objid=c.oid and d.classid='pg_catalog.pg_class'::regclass and d.deptype='e')
 union all
 select jsonb_build_object('kind','constraint','key',n.nspname||'.'||c.relname||'.'||co.conname,'value',pg_catalog.pg_get_constraintdef(co.oid,true)) from pg_catalog.pg_constraint co join pg_catalog.pg_class c on c.oid=co.conrelid join pg_catalog.pg_namespace n on n.oid=c.relnamespace where n.nspname in ('public','touchline_private')
 union all
 select jsonb_build_object('kind','function','key',n.nspname||'.'||p.proname||'('||pg_catalog.pg_get_function_identity_arguments(p.oid)||')','value',jsonb_build_object('body',p.prosrc,'owner',pg_catalog.pg_get_userbyid(p.proowner),'language',l.lanname,'return',pg_catalog.pg_get_function_result(p.oid),'securityDefiner',p.prosecdef,'volatility',p.provolatile,'strict',p.proisstrict,'config',p.proconfig))
 from pg_catalog.pg_proc p join pg_catalog.pg_namespace n on n.oid=p.pronamespace join pg_catalog.pg_language l on l.oid=p.prolang where n.nspname in ('public','touchline_private') and p.prokind='f'
 and not exists(select 1 from pg_catalog.pg_depend d where d.objid=p.oid and d.classid='pg_catalog.pg_proc'::regclass and d.deptype='e')
 union all
 select jsonb_build_object('kind','policy','key',n.nspname||'.'||c.relname||'.'||p.polname,'value',jsonb_build_object('command',p.polcmd,'permissive',p.polpermissive,'roles',(select jsonb_agg(case when r=0 then 'PUBLIC' else pg_catalog.pg_get_userbyid(r)::text end order by r) from unnest(p.polroles) r),'using',pg_catalog.pg_get_expr(p.polqual,p.polrelid),'check',pg_catalog.pg_get_expr(p.polwithcheck,p.polrelid))) from pg_catalog.pg_policy p join pg_catalog.pg_class c on c.oid=p.polrelid join pg_catalog.pg_namespace n on n.oid=c.relnamespace where n.nspname in ('public','touchline_private')
 union all
 select jsonb_build_object('kind','trigger','key',n.nspname||'.'||c.relname||'.'||t.tgname,'value',jsonb_build_object('definition',pg_catalog.pg_get_triggerdef(t.oid,true),'enabled',t.tgenabled)) from pg_catalog.pg_trigger t join pg_catalog.pg_class c on c.oid=t.tgrelid join pg_catalog.pg_namespace n on n.oid=c.relnamespace where (n.nspname in ('public','touchline_private') or n.nspname='auth' and c.relname='users') and not t.tgisinternal
 union all
 select jsonb_build_object('kind','view','key',n.nspname||'.'||c.relname,'value',jsonb_build_object('definition',pg_catalog.pg_get_viewdef(c.oid,true),'options',c.reloptions)) from pg_catalog.pg_class c join pg_catalog.pg_namespace n on n.oid=c.relnamespace where n.nspname in ('public','touchline_private') and c.relkind in ('v','m')
 union all
 select jsonb_build_object('kind','table-grant','key',n.nspname||'.'||c.relname||':'||case when a.grantee=0 then 'PUBLIC' else pg_catalog.pg_get_userbyid(a.grantee)::text end||':'||a.privilege_type,'value',a.is_grantable) from pg_catalog.pg_class c join pg_catalog.pg_namespace n on n.oid=c.relnamespace cross join lateral pg_catalog.aclexplode(coalesce(c.relacl,pg_catalog.acldefault('r',c.relowner))) a where n.nspname in ('public','touchline_private') and c.relkind in ('r','v','m','f','p') and a.grantee<>c.relowner
 union all
 select jsonb_build_object('kind','function-grant','key',n.nspname||'.'||p.proname||'('||pg_catalog.pg_get_function_identity_arguments(p.oid)||'):'||case when a.grantee=0 then 'PUBLIC' else pg_catalog.pg_get_userbyid(a.grantee)::text end||':'||a.privilege_type,'value',a.is_grantable) from pg_catalog.pg_proc p join pg_catalog.pg_namespace n on n.oid=p.pronamespace cross join lateral pg_catalog.aclexplode(coalesce(p.proacl,pg_catalog.acldefault('f',p.proowner))) a where n.nspname in ('public','touchline_private') and a.grantee<>p.proowner and not exists(select 1 from pg_catalog.pg_depend d where d.objid=p.oid and d.classid='pg_catalog.pg_proc'::regclass and d.deptype='e')
 union all
 select jsonb_build_object('kind','schema-owner','key',n.nspname,'value',pg_catalog.pg_get_userbyid(n.nspowner)) from pg_catalog.pg_namespace n where n.nspname='touchline_private'
 union all
 select jsonb_build_object('kind','schema-grant','key',n.nspname||':'||case when a.grantee=0 then 'PUBLIC' else pg_catalog.pg_get_userbyid(a.grantee)::text end||':'||a.privilege_type,'value',a.is_grantable) from pg_catalog.pg_namespace n cross join lateral pg_catalog.aclexplode(coalesce(n.nspacl,pg_catalog.acldefault('n',n.nspowner))) a where n.nspname in ('public','touchline_private') and a.grantee<>n.nspowner
 union all
 select jsonb_build_object('kind','column-grant','key',n.nspname||'.'||c.relname||'.'||col.attname||':'||case when acl.grantee=0 then 'PUBLIC' else pg_catalog.pg_get_userbyid(acl.grantee)::text end||':'||acl.privilege_type,'value',acl.is_grantable) from pg_catalog.pg_attribute col join pg_catalog.pg_class c on c.oid=col.attrelid join pg_catalog.pg_namespace n on n.oid=c.relnamespace cross join lateral pg_catalog.aclexplode(col.attacl) acl where n.nspname in ('public','touchline_private') and col.attnum>0 and not col.attisdropped
 union all
 select jsonb_build_object('kind','unknown-schema','key',n.nspname,'value',true) from pg_catalog.pg_namespace n where n.nspname not in ('public','touchline_private','information_schema','auth','extensions','storage','realtime','supabase_functions','supabase_migrations','graphql','graphql_public','net','vault','pgbouncer','pgsodium','pgsodium_masks','pgtle','_realtime','_analytics','_supavisor') and n.nspname not like 'pg\_%' escape '\'
) entries
